const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
const lines = input.trim().split(/\n/);

lines.forEach(line => {
    const parts = line.trim().split(/\s+/);
    if (parts.length === 2) {
        const s1 = parts[0].split('').sort().join('');
        const s2 = parts[1].split('').sort().join('');
        console.log(s1 === s2 ? "Anagram" : "Not Anagram");
    }
});
